type ReportStatus = "SUBMITTED" | "PENDING" | "OVERDUE" | "DRAFT" | "REJECTED";
type ReportType = "API_14C" | "BSEE_OGOR" | "EPA_SUBPART_W" | "PHMSA" | "STATE_RRC" | "STATE_NDIC";

interface RegulatoryReport {
  report_id: string;
  type: ReportType;
  title: string;
  agency: string;
  period: string;
  due_date: string;
  submitted_date?: string;
  status: ReportStatus;
  wells_covered: number;
  completeness_pct: number;
  submission_ref?: string;
  notes?: string;
}

interface ComplianceMetric {
  agency: string;
  total: number;
  submitted: number;
  pending: number;
  overdue: number;
}

