// ── Helpers ───────────────────────────────────────────────────────────────────

function statusConfig(status: ReportStatus) {
  const map: Record<ReportStatus, { label: string; color: string; bg: string; icon: typeof CheckCircle2 }> = {
    SUBMITTED: { label: "Submitted", color: "text-emerald-400", bg: "bg-emerald-500/10 border-emerald-700/30", icon: CheckCircle2 },
    PENDING:   { label: "Pending",   color: "text-amber-400",   bg: "bg-amber-500/10 border-amber-700/30",   icon: Clock },
    OVERDUE:   { label: "Overdue",   color: "text-red-400",     bg: "bg-red-500/10 border-red-700/30",       icon: AlertTriangle },
    DRAFT:     { label: "Draft",     color: "text-blue-400",    bg: "bg-blue-500/10 border-blue-700/30",     icon: FileText },
    REJECTED:  { label: "Rejected",  color: "text-red-400",     bg: "bg-red-500/10 border-red-700/30",       icon: AlertTriangle },
  };
  return map[status];
}

function typeConfig(type: ReportType) {
  const map: Record<ReportType, { label: string; color: string }> = {
    API_14C:       { label: "API 14C",    color: "text-orange-400" },
    BSEE_OGOR:     { label: "BSEE OGOR",  color: "text-blue-400" },
    EPA_SUBPART_W: { label: "EPA Sub-W",  color: "text-green-400" },
    PHMSA:         { label: "PHMSA",      color: "text-purple-400" },
    STATE_RRC:     { label: "Texas RRC",  color: "text-amber-400" },
    STATE_NDIC:    { label: "NDIC",       color: "text-cyan-400" },
  };
  return map[type];
}

function daysUntilDue(dueDate: string): number {
  const due = new Date(dueDate);
  const now = new Date();
  return Math.ceil((due.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
}

// ── Sub-components ────────────────────────────────────────────────────────────

// Map frontend report types to backend enum values
const BACKEND_TYPE_MAP: Partial<Record<ReportType, "API_14C" | "BSEE_OGOR" | "EPA_SUBPART_W" | "MOCCAE" | "ADNOC_HSE" | "KOC_ENV" | "NCSC_INCIDENT">> = {
  API_14C: "API_14C",
  BSEE_OGOR: "BSEE_OGOR",
  EPA_SUBPART_W: "EPA_SUBPART_W",
  // Map additional report types to the closest backend enum value
  STATE_RRC: "BSEE_OGOR",   // Texas RRC uses BSEE OGOR format
  STATE_NDIC: "BSEE_OGOR",  // NDIC uses BSEE OGOR format
  PHMSA: "API_14C",          // PHMSA uses API 14C format
};

function ReportRow({ report, onPreview }: { report: RegulatoryReport; onPreview?: (url: string, title: string) => void }) {
  const sc = statusConfig(report.status);
  const tc = typeConfig(report.type);
  const StatusIcon = sc.icon;
  const days = daysUntilDue(report.due_date);
  const [generating, setGenerating] = useState(false);
  const [pdfUrl, setPdfUrl] = useState<string | null>(null);
  const [dbReportId, setDbReportId] = useState<number | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const AUTHORITY_MAP: Record<string, "ADNOC" | "KOC" | "ARAMCO" | "MOCCAE" | "BSEE" | "EPA" | "NCSC"> = {
    "ADNOC": "ADNOC", "KOC": "KOC", "Saudi Aramco": "ARAMCO", "ARAMCO": "ARAMCO",
    "MOCCAE": "MOCCAE", "BSEE": "BSEE", "EPA": "EPA", "NCSC": "NCSC",
  };

  const submitToAuthority = trpc.regulatory.submitToAuthority.useMutation({
    onSuccess: (data) => {
      setSubmitting(false);
      toast.success(`Submitted to ${data.authority}`, {
        description: `Reference: ${data.submissionRef}`,
        duration: 8000,
      });
    },
    onError: (err) => {
      setSubmitting(false);
      toast.error("Submission failed", { description: err.message });
    },
  });

  const { t } = useTranslation();

  const generateBilingual = trpc.regulatory.generateBilingualPDF.useMutation({
    onSuccess: (data) => {
      // Open the bilingual HTML report in a new window
      const win = window.open("", "_blank");
      if (win) {
        win.document.write(data.html);
        win.document.close();
      }
      toast.success(`Bilingual report generated — ${data.titleEn} / ${data.titleAr}`, { duration: 6000 });
    },
    onError: (err) => toast.error(`Bilingual PDF failed: ${err.message}`),
  });

  const generatePDF = trpc.regulatory.generatePDF.useMutation({
    onSuccess: (data) => {
      setGenerating(false);
      setPdfUrl(data.url);
      setDbReportId(data.id);
      toast.success(`${report.title} — PDF generated`, {
        description: (
          <span>
            <a href={data.url} target="_blank" rel="noopener noreferrer" className="underline text-blue-400">
              Download PDF ({(data.sizeBytes / 1024).toFixed(0)} KB)
            </a>
            {" · "}
            <button
              onClick={() => onPreview?.(data.url, report.title)}
              className="underline text-amber-400"
            >
              Preview
            </button>
          </span>
        ) as any,
        duration: 10000,
      });
    },
    onError: (err) => {
      setGenerating(false);
      toast.error("PDF generation failed", { description: err.message });
    },
  });

  async function handleGenerate() {
    const backendType = BACKEND_TYPE_MAP[report.type];
    if (!backendType) {
      // Fallback for types not yet in backend enum
      setGenerating(true);
      await new Promise(r => setTimeout(r, 1200));
      setGenerating(false);
      toast.success(`${report.title} — report package generated`, {
        description: "PDF + XML e-filing package ready for download",
      });
      return;
    }
    setGenerating(true);
    generatePDF.mutate({
      reportType: backendType,
      period: report.period,
      language: "EN",
      notes: report.notes,
    });
  }

  function handleSubmit() {
    if (!dbReportId) {
      toast.warning("Generate PDF first", { description: "A PDF must be generated before submitting to the authority." });
      return;
    }
    const authority = AUTHORITY_MAP[report.agency];
    if (!authority) {
      toast.warning("Authority not mapped", { description: `No e-filing endpoint configured for ${report.agency}` });
      return;
    }
    setSubmitting(true);
    submitToAuthority.mutate({ id: dbReportId, authority });
  }

  return (
    <div className="rounded-lg border border-border/50 bg-card p-4 hover:border-border transition-colors">
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1 flex-wrap">
            <span className={`text-[10px] font-mono font-bold px-1.5 py-0.5 rounded border ${tc.color} bg-card border-border/50`}>
              {tc.label}
            </span>
            <span className={`text-[10px] font-medium px-1.5 py-0.5 rounded border ${sc.bg} ${sc.color}`}>
              <StatusIcon className="w-2.5 h-2.5 inline mr-1" />
              {sc.label}
            </span>
            {report.submission_ref && (
              <span className="text-[10px] font-mono text-muted-foreground">{report.submission_ref}</span>
            )}
          </div>
          <div className="font-[Syne] font-bold text-sm text-foreground">{report.title}</div>
          <div className="text-xs text-muted-foreground mt-0.5">{report.agency} · {report.period}</div>
          {report.notes && (
            <div className="text-xs text-muted-foreground mt-1 italic">{report.notes}</div>
          )}
        </div>

        <div className="flex flex-col items-end gap-2 shrink-0">
          <div className="text-right">
            <div className="text-xs text-muted-foreground">Due {report.due_date}</div>
            {report.status !== "SUBMITTED" && (
              <div className={`text-xs font-mono font-bold ${days < 0 ? "text-red-400" : days < 7 ? "text-amber-400" : "text-muted-foreground"}`}>
                {days < 0 ? `${Math.abs(days)}d overdue` : `${days}d remaining`}
              </div>
            )}
          </div>
          <div className="flex items-center gap-1.5">
            {pdfUrl && (
              <Button
                variant="outline"
                size="sm"
                className="h-7 text-xs border-amber-700/40 text-amber-400 hover:text-amber-300"
                onClick={() => onPreview?.(pdfUrl, report.title)}
              >
                <Eye className="w-3 h-3 mr-1" />
                Preview
              </Button>
            )}
            <Button
              variant="outline"
              size="sm"
              className="h-7 text-xs border-border/50"
              onClick={handleGenerate}
              disabled={generating}
            >
              {generating ? (
                <span className="w-3 h-3 mr-1 border border-foreground/30 border-t-foreground rounded-full animate-spin inline-block" />
              ) : (
                <Download className="w-3 h-3 mr-1" />
              )}
              Generate
            </Button>
            <Button
              size="sm"
              variant="outline"
              className="h-7 text-xs border-amber-700/40 text-amber-400 hover:bg-amber-950/30"
              onClick={() => generateBilingual.mutate({ reportType: BACKEND_TYPE_MAP[report.type] ?? report.type, period: report.period, language: "bilingual" })}
              disabled={generateBilingual.isPending}
              title="Generate bilingual Arabic/English report"
            >
              <Globe className="w-3 h-3 mr-1" />
              AR/EN
            </Button>
            {(report.status === "PENDING" || report.status === "DRAFT") && (
              <Button
                size="sm"
                className="h-7 text-xs bg-amber-600 hover:bg-amber-700 text-white"
                onClick={handleSubmit}
                disabled={submitting}
              >
                {submitting ? (
                  <span className="w-3 h-3 mr-1 border border-white/30 border-t-white rounded-full animate-spin inline-block" />
                ) : (
                  <Send className="w-3 h-3 mr-1" />
                )}
                {submitting ? "Submitting..." : "Submit"}
              </Button>
            )}
          </div>
        </div>
      </div>

      {report.completeness_pct < 100 && (
        <div className="mt-3">
          <div className="flex items-center justify-between text-[10px] text-muted-foreground mb-1">
            <span>Data completeness</span>
            <span className="font-mono">{report.completeness_pct}%</span>
          </div>
          <Progress
            value={report.completeness_pct}
            className="h-1"
          />
        </div>
      )}
    </div>
  );
}

function ComplianceBar({ metric }: { metric: ComplianceMetric }) {
  const pct = Math.round((metric.submitted / metric.total) * 100);
  return (
    <div className="space-y-1">
      <div className="flex items-center justify-between text-xs">
        <span className="font-medium text-foreground">{metric.agency}</span>
        <span className="font-mono text-muted-foreground">
          {metric.submitted}/{metric.total}
          {metric.overdue > 0 && <span className="text-red-400 ml-1">({metric.overdue} overdue)</span>}
        </span>
      </div>
      <div className="h-2 rounded-full bg-muted overflow-hidden flex">
        <div className="bg-emerald-500 h-full transition-all" style={{ width: `${(metric.submitted/metric.total)*100}%` }} />
        <div className="bg-amber-500 h-full transition-all" style={{ width: `${(metric.pending/metric.total)*100}%` }} />
        <div className="bg-red-500 h-full transition-all" style={{ width: `${(metric.overdue/metric.total)*100}%` }} />
      </div>
    </div>
  );
}

