// ── Submission History Panel ──────────────────────────────────────────────────

function SubmissionHistoryPanel() {
  const { user } = useAuth();
  const isAdmin = (user as any)?.role === "admin";
  const { data: history, isLoading, refetch } = trpc.regulatory.submissionHistory.useQuery({ limit: 100 });
  const resubmitMutation = trpc.regulatory.resubmit.useMutation({
    onSuccess: (data) => {
      toast.success("Re-submitted successfully", { description: data.message });
      refetch();
    },
    onError: (err) => toast.error("Re-submit failed", { description: err.message }),
  });
  const updateStatusMutation = trpc.regulatory.updateSubmissionStatus.useMutation({
    onSuccess: (data) => {
      toast.success(`Status updated to ${data.status}`, { description: data.message });
      refetch();
    },
    onError: (err) => toast.error("Status update failed", { description: err.message }),
  });

  const statusBadge = (status: string) => {
    if (status === "ACCEPTED") return <Badge className="bg-emerald-600/20 text-emerald-400 border-emerald-600/30 text-xs">Accepted</Badge>;
    if (status === "REJECTED") return <Badge className="bg-rose-600/20 text-rose-400 border-rose-600/30 text-xs">Rejected</Badge>;
    return <Badge className="bg-amber-600/20 text-amber-400 border-amber-600/30 text-xs">Submitted</Badge>;
  };

  const authorityFromRef = (ref: string | null) => {
    if (!ref) return "—";
    const prefix = ref.split("-")[0];
    const map: Record<string, string> = {
      ADN: "ADNOC", KOC: "KOC", SAR: "ARAMCO",
      MOC: "MOCCAE", BSE: "BSEE", EPA: "EPA", NCS: "NCSC",
    };
    return map[prefix] ?? prefix;
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <RefreshCw className="w-5 h-5 animate-spin text-amber-500 mr-2" />
        <span className="text-sm text-muted-foreground">Loading submission history...</span>
      </div>
    );
  }

  if (!history || history.length === 0) {
    return (
      <Card className="border-border/50">
        <CardContent className="py-12 text-center">
          <Send className="w-8 h-8 text-muted-foreground mx-auto mb-3" />
          <p className="text-sm text-muted-foreground">No submitted reports yet.</p>
          <p className="text-xs text-muted-foreground mt-1">Generate a report and click Submit to see history here.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-border/50">
      <CardHeader className="pb-3">
        <CardTitle className="font-[Syne] text-sm font-bold flex items-center gap-2">
          <Send className="w-4 h-4 text-amber-500" />
          Submission History
          <Badge variant="outline" className="text-xs ml-1">{history.length}</Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="p-0">
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-border/50 bg-muted/20">
                {["Report ID", "Type", "Period", "Authority", "Ref #", "Submitted", "Status", ""].map(h => (
                  <th key={h} className="text-left px-4 py-2 text-muted-foreground font-medium">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {history.map(row => (
                <tr key={row.id} className="border-b border-border/30 hover:bg-muted/10 transition-colors">
                  <td className="px-4 py-2.5 font-mono text-amber-400/80">{row.reportId}</td>
                  <td className="px-4 py-2.5 text-muted-foreground">{row.reportType.replace(/_/g, " ")}</td>
                  <td className="px-4 py-2.5">{row.period}</td>
                  <td className="px-4 py-2.5">{authorityFromRef(row.submissionRef ?? null)}</td>
                  <td className="px-4 py-2.5 font-mono text-xs text-muted-foreground">
                    {row.submissionRef ?? "—"}
                  </td>
                  <td className="px-4 py-2.5 text-muted-foreground">
                    {row.submittedAt ? new Date(row.submittedAt).toLocaleDateString() : "—"}
                  </td>
                  <td className="px-4 py-2.5">{statusBadge(row.status)}</td>
                  <td className="px-4 py-2.5">
                    <div className="flex items-center gap-1 flex-wrap">
                      {row.status === "REJECTED" && (
                        <Button
                          size="sm"
                          variant="outline"
                          className="h-6 text-xs px-2 border-amber-600/40 text-amber-400 hover:bg-amber-600/10"
                          disabled={resubmitMutation.isPending}
                          onClick={() => resubmitMutation.mutate({
                            id: row.id,
                            authority: (authorityFromRef(row.submissionRef ?? null) as any) || "ADNOC",
                          })}
                        >
                          {resubmitMutation.isPending ? <RefreshCw className="w-3 h-3 animate-spin" /> : <Send className="w-3 h-3" />}
                          <span className="ml-1">Re-submit</span>
                        </Button>
                      )}
                      {row.fileUrl && (
                        <a href={row.fileUrl} target="_blank" rel="noopener noreferrer">
                          <Button size="sm" variant="ghost" className="h-6 text-xs px-2 text-muted-foreground hover:text-foreground">
                            <ExternalLink className="w-3 h-3" />
                          </Button>
                        </a>
                      )}
                      {/* Admin-only status simulation buttons */}
                      {isAdmin && row.status === "SUBMITTED" && (
                        <>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 text-xs px-2 text-emerald-400 hover:bg-emerald-600/10 border border-emerald-700/30"
                            disabled={updateStatusMutation.isPending}
                            onClick={() => updateStatusMutation.mutate({ id: row.id, status: "ACCEPTED" })}
                            title="Admin: Mark as Accepted"
                          >
                            <CheckCircle2 className="w-3 h-3 mr-1" />
                            Accept
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-6 text-xs px-2 text-rose-400 hover:bg-rose-600/10 border border-rose-700/30"
                            disabled={updateStatusMutation.isPending}
                            onClick={() => updateStatusMutation.mutate({ id: row.id, status: "REJECTED", notes: "Rejected by admin (simulation)" })}
                            title="Admin: Mark as Rejected"
                          >
                            <AlertTriangle className="w-3 h-3 mr-1" />
                            Reject
                          </Button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </CardContent>
    </Card>
  );
}

// ── Regulatory Calendar ───────────────────────────────────────────────────────
function RegulatoryCalendar() {
  const { data: calendarItems, isLoading } = trpc.regulatory.calendarData.useQuery();
  const [viewMonth, setViewMonth] = useState(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
  });

  const [viewYear, viewMonthNum] = viewMonth.split("-").map(Number);

  const daysInMonth = new Date(viewYear, viewMonthNum, 0).getDate();
  const firstDayOfWeek = new Date(viewYear, viewMonthNum - 1, 1).getDay();

  // Group items by day
  const byDay: Record<number, typeof calendarItems> = {};
  (calendarItems ?? []).forEach((item: any) => {
    if (!item.dueDate) return;
    const d = new Date(item.dueDate);
    if (d.getFullYear() === viewYear && d.getMonth() + 1 === viewMonthNum) {
      const day = d.getDate();
      if (!byDay[day]) byDay[day] = [];
      byDay[day]!.push(item);
    }
  });

  const statusColor = (status: string) => {
    if (status === "SUBMITTED" || status === "ACCEPTED") return "bg-emerald-500/20 text-emerald-400 border-emerald-700/40";
    if (status === "REJECTED") return "bg-red-500/20 text-red-400 border-red-700/40";
    const dueDate = new Date();
    return "bg-amber-500/20 text-amber-400 border-amber-700/40";
  };

  const prevMonth = () => {
    const d = new Date(viewYear, viewMonthNum - 2, 1);
    setViewMonth(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`);
  };
  const nextMonth = () => {
    const d = new Date(viewYear, viewMonthNum, 1);
    setViewMonth(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`);
  };

  const monthName = new Date(viewYear, viewMonthNum - 1, 1).toLocaleString("default", { month: "long", year: "numeric" });

  return (
    <Card className="border-border/50">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <Calendar className="w-4 h-4 text-amber-500" />
            Regulatory Calendar — {monthName}
          </CardTitle>
          <div className="flex gap-2">
            <Button size="sm" variant="outline" className="h-7 text-xs" onClick={prevMonth}>‹ Prev</Button>
            <Button size="sm" variant="outline" className="h-7 text-xs" onClick={nextMonth}>Next ›</Button>
          </div>
        </div>
        <div className="flex gap-3 text-xs text-muted-foreground mt-1">
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-emerald-500" />Submitted/Accepted</span>
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-amber-500" />Due Soon/Draft</span>
          <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-red-500" />Overdue/Rejected</span>
        </div>
      </CardHeader>
      <CardContent>
        {isLoading && <p className="text-sm text-muted-foreground">Loading calendar…</p>}
        {!isLoading && (
          <div className="grid grid-cols-7 gap-1">
            {["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(d => (
              <div key={d} className="text-center text-xs text-muted-foreground font-medium py-1">{d}</div>
            ))}
            {Array.from({ length: firstDayOfWeek }).map((_, i) => (
              <div key={`empty-${i}`} />
            ))}
            {Array.from({ length: daysInMonth }).map((_, i) => {
              const day = i + 1;
              const items = byDay[day] ?? [];
              const isToday = new Date().getDate() === day &&
                new Date().getMonth() + 1 === viewMonthNum &&
                new Date().getFullYear() === viewYear;
              return (
                <div key={day} className={`min-h-[64px] rounded border p-1 ${isToday ? "border-amber-500/60 bg-amber-950/20" : "border-border/30 bg-card/30"}`}>
                  <div className={`text-xs font-medium mb-1 ${isToday ? "text-amber-400" : "text-muted-foreground"}`}>{day}</div>
                  {items.slice(0, 2).map((item: any) => (
                    <div key={item.id} className={`text-xs px-1 py-0.5 rounded border mb-0.5 truncate ${statusColor(item.status)}`}
                      title={`${item.reportType} — ${item.status}`}>
                      {item.reportType?.replace("_", " ")}
                    </div>
                  ))}
                  {items.length > 2 && (
                    <div className="text-xs text-muted-foreground">+{items.length - 2} more</div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}
